across()
across(cols, fns, names:) applies functions to several columns inside mutate() or summarize(). Grouping columns are never selected. fns is one function or an associative array of named functions. Output names default to {col} for one function and {col}_{fn} for several.

PHP 8.5+PHP 8.3–8.4


$schools = DataFrame::fromCsv('schools.csv') |&gt; group_by('school');

// Phplyr helpers can be passed by name; each gets the column name.
echo $schools |&gt;
    summarize(across(where('numeric'), ['avg' =&gt; mean(...), 'sd' =&gt; sd(...)])) |&gt;
    head(3);

// Other closures get the column's values (summarize) or each value (mutate).
echo "\n", $schools |&gt;
    summarize(across(['study_hours', 'score'], fn (array $v) =&gt; round(\max($v) - \min($v), 1), names: 'range_{col}')) |&gt;
    head(3);
echo "\n", $schools |&gt; ungroup() |&gt; mutate(across(ends_with('score'), fn ($v) =&gt; round($v))) |&gt; head(3);


$schools = phplyr(DataFrame::fromCsv('schools.csv'))-&gt;groupBy('school')-&gt;get();

// Phplyr helpers can be passed by name; each gets the column name.
echo phplyr($schools)
    -&gt;summarize(across(where('numeric'), ['avg' =&gt; mean(...), 'sd' =&gt; sd(...)]))
    -&gt;head(3);

// Other closures get the column's values (summarize) or each value (mutate).
echo "\n", phplyr($schools)
    -&gt;summarize(across(['study_hours', 'score'], fn (array $v) =&gt; round(\max($v) - \min($v), 1), names: 'range_{col}'))
    -&gt;head(3);
echo "\n", phplyr($schools)-&gt;ungroup()-&gt;mutate(across(ends_with('score'), fn ($v) =&gt; round($v)))-&gt;head(3);



