A first pipeline
Keep the students who studied at least five hours, summarize each school, and print the five schools with the highest average score.
composer require phpstats/phplyr
curl -O https://raw.githubusercontent.com/phpstats/phplyr/v0.4.5/docs/data/schools.csv

PHP 8.5+PHP 8.3–8.4


use Phibble\DataFrame;
use function Phplyr\{filter, group_by, summarize};
use function Phplyr\{arrange, head, desc, n, mean, sd};

$schools = DataFrame::fromCsv('schools.csv');

echo $schools |&gt;
    filter(fn ($r) =&gt; $r-&gt;study_hours &gt;= 5) |&gt;
    group_by('school') |&gt;
    summarize(
        students: n(),
        avg_score: mean('score'),
        sd_score: sd('score'),
    ) |&gt;
    arrange(desc('avg_score')) |&gt;
    head(5);


use Phibble\DataFrame;
use function Phplyr\{phplyr, desc, n, mean, sd};

$schools = DataFrame::fromCsv('schools.csv');

echo phplyr($schools)
    -&gt;filter(fn ($r) =&gt; $r-&gt;study_hours &gt;= 5)
    -&gt;groupBy('school')
    -&gt;summarize(
        students: n(),
        avg_score: mean('score'),
        sd_score: sd('score'),
    )
    -&gt;arrange(desc('avg_score'))
    -&gt;head(5);



