ntile() splits the students into four groups of nearly equal size by study hours.
The odds ratio is for one more study hour at the same practice score. It describes an association in these observational data.

Clinic calls by staffing
clinic.csv has visitors, staff, and calls for 120 days.

PHP 8.5+PHP 8.3–8.4


// Mean calls by staffing level and visitor volume, as a
// cross-tabulation.
$levels = ['low', 'mid', 'high'];

echo DataFrame::fromCsv('clinic.csv') |&gt;
    mutate(
        staffing: case_when(
            [fn ($r) =&gt; $r-&gt;staff &lt; 4, 'low'],
            [fn ($r) =&gt; $r-&gt;staff &lt; 6, 'mid'],
            default: 'high',
        ),
        volume: if_else(
            fn ($r) =&gt; $r-&gt;visitors &gt;= 250,
            'busy',
            'quiet',
        ),
    ) |&gt;
    group_by('staffing', 'volume') |&gt;
    summarize(mean_calls: mean('calls'), _groups: 'drop') |&gt;
    mutate(
        mean_calls: fn ($r) =&gt; round($r-&gt;mean_calls, 2),
    ) |&gt;
    pivot_wider(
        namesFrom: 'volume',
        valuesFrom: 'mean_calls',
        namesSort: true,
    ) |&gt;
    arrange(
        fn ($r) =&gt; array_search($r-&gt;staffing, $levels),
    );


// Mean calls by staffing level and visitor volume, as a
// cross-tabulation.
$levels = ['low', 'mid', 'high'];

echo phplyr(DataFrame::fromCsv('clinic.csv'))
    -&gt;mutate(
        staffing: case_when(
            [fn ($r) =&gt; $r-&gt;staff &lt; 4, 'low'],
            [fn ($r) =&gt; $r-&gt;staff &lt; 6, 'mid'],
            default: 'high',
        ),
        volume: if_else(
            fn ($r) =&gt; $r-&gt;visitors &gt;= 250,
            'busy',
            'quiet',
        ),
    )
    -&gt;groupBy('staffing', 'volume')
    -&gt;summarize(mean_calls: mean('calls'), _groups: 'drop')
    -&gt;mutate(
        mean_calls: fn ($r) =&gt; round($r-&gt;mean_calls, 2),
    )
